'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var zeros = require( '@stdlib/array/zeros' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var Float64Array = require( '@stdlib/array/float64' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dorm2r = require( './../lib/dorm2r.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var SIDES = [
	'left',
	'right'
];
var TRANS = [
	'no-transpose',
	'transpose'
];


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {string} side - specifies the side of multiplication
* @param {string} trans - specifies the operation to be performed
* @param {PositiveInteger} N - number of rows/columns in matrix C
* @returns {Function} benchmark function
*/
function createBenchmark( order, side, trans, N ) {
	var opts;
	var work;
	var tau;
	var A;
	var C;

	opts = {
		'dtype': 'float64'
	};

	A = zeros( N*N, 'float64' );
	C = uniform( N*N, -10.0, 10.0, opts );
	tau = uniform( N, 0.0, 2.0, opts );
	work = new Float64Array( N );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dorm2r( order, side, trans, N, N, N, A, N, tau, C, N, work );
			if ( isnan( z[ i%z.length ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var trans;
	var side;
	var ord;
	var min;
	var max;
	var N;
	var f;
	var i;
	var j;
	var k;

	min = 1; // 10^min
	max = 3; // 10^max

	for ( i = 0; i < LAYOUTS.length; i++ ) {
		ord = LAYOUTS[ i ];
		for ( j = 0; j < SIDES.length; j++ ) {
			side = SIDES[ j ];
			for ( k = 0; k < TRANS.length; k++ ) {
				trans = TRANS[ k ];
				for ( N = min; N <= max; N++ ) {
					f = createBenchmark( ord, side, trans, floor( pow( pow( 10, N ), 1.0/2.0 ) ) );
					bench( format( '%s:order=%s,side=%s,trans=%s,size=%d', pkg, ord, side, trans, N*N ), f );
				}
			}
		}
	}
}

main();
